/* DARK XRAY Control V2 — structured DNS / Outbounds / Routing / Balancers / Observatory. */
(function(){
'use strict';
if(typeof enginePage!=='function'||typeof runAction!=='function')return;
const baseEnginePage=enginePage,baseRunAction=runAction;
state.xv2={tab:'general'};
const L=(en,fa)=>((localStorage.getItem('dark_lang')||'en')==='fa'?fa:en);
const xesc=v=>e(String(v??''));
function xtabs(){const xs=[['general',L('General','عمومی')],['dns','DNS'],['outbounds',L('Outbounds','اوتباندها')],['routing',L('Routing','روتینگ')],['balancers',L('Balancers','بالانسرها')],['observatory','Observatory'],['advanced',L('Advanced JSON','JSON پیشرفته')]];return `<nav class="xv2-tabs">${xs.map(([k,l])=>`<button data-act="xv2tab" data-tab="${k}" class="${state.xv2.tab===k?'active':''}">${xesc(l)}</button>`).join('')}</nav>`;}
function xcard(title,sub,body){return `<article class="panel xv2-card"><h3>${xesc(title)}</h3>${sub?`<p>${xesc(sub)}</p>`:''}${body}</article>`;}
async function allData(){const keys=['dns','outbounds','routing','observatory','policy'];const out={};await Promise.all(keys.map(async k=>{out[k]=(await api('/api/settings/'+k)).value;}));out.core=await api('/api/core/state');try{out.smart=await api('/api/smart-routing/plan');}catch{out.smart=null;}try{out.smartRevisions=(await api('/api/smart-routing/revisions')).items||[];}catch{out.smartRevisions=[];}try{out.smartRollouts=(await api('/api/smart-routing/rollouts')).items||[];}catch{out.smartRollouts=[];}return out;}
function general(d){let r=d.core;return `<div class="xv2-grid">${xcard(L('Xray runtime','اجرای Xray'),L('Local child process controlled by DARK.','پردازش محلی Xray تحت کنترل DARK.'),`<div class="xv2-kv"><div><span>${L('State','وضعیت')}</span><b>${xesc(r.state)}</b></div><div><span>PID</span><b class="mono">${xesc(r.pid||'—')}</b></div><div><span>${L('Version','نسخه')}</span><b class="mono">${xesc(r.version||'—')}</b></div><div><span>${L('Config dirty','تغییرات اعمال‌نشده')}</span><b>${r.dirty?L('Yes','بله'):L('No','خیر')}</b></div><div><span>${L('Desired state','وضعیت مطلوب')}</span><b>${r.desired_running?L('Running','روشن'):L('Stopped','خاموش')}</b></div><div><span>${L('Auto recoveries','بازیابی خودکار')}</span><b>${xesc(r.automatic_recoveries||0)}</b></div></div><div class="xv2-actions" style="margin-top:12px">${button(L('Validate','اعتبارسنجی'),'xv2validate','check')}${button(L('Restart / Apply','ری‌استارت / اعمال'),'xv2restart','refresh','',true)}</div>`)}${xcard(L('Control model','مدل کنترل'),L('DB save and Xray apply remain separate on purpose.','ذخیره دیتابیس و اعمال Xray عمداً جدا هستند.'),`<div class="notice ${r.last_error?'error':''}">${xesc(r.last_error||L('No runtime error recorded.','خطای Runtime ثبت نشده است.'))}</div><p>${L('Every structured editor writes DARK state first. Use Validate before applying disruptive changes.','هر ویرایشگر ابتدا وضعیت DARK را ذخیره می‌کند. قبل از اعمال تغییرات از Validate استفاده کن.')}</p>`)}</div>`;}
function dns(d){const v=d.dns||{},servers=Array.isArray(v.servers)?v.servers:[];return `<div class="xv2-grid">${xcard('DNS',L('Native Xray DNS settings.','تنظیمات DNS بومی Xray.'),`<div class="xv2-kv"><div><span>${L('Servers','سرورها')}</span><b>${servers.length}</b></div><div><span>queryStrategy</span><b>${xesc(v.queryStrategy||'UseIP')}</b></div><div><span>disableCache</span><b>${String(!!v.disableCache)}</b></div><div><span>tag</span><b>${xesc(v.tag||'—')}</b></div></div><div class="xv2-actions" style="margin-top:12px">${button(L('Edit DNS','ویرایش DNS'),'xv2dnsedit','edit','',true)}</div>`)}${xcard(L('Configured servers','سرورهای تنظیم‌شده'),' ',servers.length?`<div class="xv2-list">${servers.map((s,i)=>`<div class="xv2-item"><b>${i+1}</b> <span class="mono">${xesc(typeof s==='string'?s:JSON.stringify(s))}</span></div>`).join('')}</div>`:empty(L('No DNS servers.','سرور DNS تعریف نشده است.')))}</div>`;}
function outboundEndpoint(o){let s=o.settings||{},p=o.protocol;if(p==='vless'||p==='hysteria')return s.address&&s.port?`${s.address}:${s.port}`:'';if(p==='vmess')return s.vnext?.[0]?.address?`${s.vnext[0].address}:${s.vnext[0].port||''}`:'';if(['trojan','shadowsocks','socks','http'].includes(p))return s.servers?.[0]?.address?`${s.servers[0].address}:${s.servers[0].port||''}`:'';if(p==='wireguard')return s.peers?.[0]?.endpoint||'';if(p==='loopback')return s.inboundTag||'';return '';}
function outboundItem(o,i){const chain=o.streamSettings?.sockopt?.dialerProxy||'',net=o.streamSettings?.network||'',sec=o.streamSettings?.security||'',endpoint=outboundEndpoint(o);return `<div class="xv2-item xv3-outbound-row"><div class="xv2-item-head"><div><b>${xesc(o.tag)}</b><br><small>${xesc(o.protocol)}${endpoint?' · '+xesc(endpoint):''}${net?' · '+xesc(net):''}${sec&&sec!=='none'?' · '+xesc(sec):''}${chain?' · via '+xesc(chain):''}</small></div><div class="xv2-actions">${button(L('Edit','ویرایش'),'xv2outedit','edit',`data-index="${i}"`)}${button(L('Clone','کپی'),'xv2outclone','copy',`data-index="${i}"`)}${button(L('Advanced JSON','JSON پیشرفته'),'xv3outraw','terminal',`data-index="${i}"`)}${button(L('Delete','حذف'),'xv2outdelete','trash',`data-index="${i}"`)}</div></div></div>`;}
function warpCandidates(d){const p=d.smart||{},planned=Array.isArray(p.warpCandidates)?p.warpCandidates:[];if(planned.length)return planned;return (Array.isArray(d.outbounds)?d.outbounds:[]).filter(o=>String(o.protocol||'').toLowerCase()==='wireguard').map(o=>({tag:o.tag,node:o.tag,region:'—',protocol:o.protocol,likelyWarp:/^(warp|wg-warp|dark-warp)/.test(String(o.tag||''))}));}
function smartWarpOutboundCard(d){const p=d.smart||{},candidates=warpCandidates(d),preferred=new Set(p.configuredWarpCandidates||[]),nodes=p.nodes?.warp_ai?.nodes||[],active=(p.activeStage7Rules||[]).some(r=>r.ruleTag==='dark-smart-warp-ai'),checks=candidates.map((c,i)=>`<label class="xv2-item"><input type="checkbox" name="warpOutboundTags" value="${xesc(c.tag)}" ${(preferred.has(c.tag)||(!preferred.size&&(c.likelyWarp||i<2)))?'checked':''}><span><b>${xesc(c.tag)}</b><br><small>${xesc(c.node||c.tag)} · ${xesc(c.region||'—')}</small></span></label>`).join('');return `<article class="panel xv2-card" style="grid-column:1/-1"><div class="xv2-toolbar"><div><h3>${L('Smart WARP AI · Outbound','Smart WARP AI · اوتباند')}</h3><p>${L('Choose reviewed WireGuard/WARP paths here. This control only builds a preview.','مسیرهای WireGuard/WARP را انتخاب کن؛ این کنترل فقط پیش‌نمایش می‌سازد.')}</p></div><span class="tag ${active?'green':'amber'}">${active?L('Configured','تنظیم‌شده'):L('Preview only','فقط پیش‌نمایش')}</span></div><div id="xv7-smart-outbound" class="xv2-form"><label><input type="checkbox" name="warpAi" checked> ${L('Smart WARP AI enabled in preview','Smart WARP AI در پیش‌نمایش فعال')}</label><div class="span-2"><b>${L('WARP outbound / node paths','مسیرهای WARP / نود')}</b><div class="xv2-list" style="margin-top:8px">${checks||`<div class="notice warning">${L('No WireGuard/WARP outbound is configured.','هیچ Outbound از نوع WireGuard/WARP تعریف نشده است.')}</div>`}</div></div><div class="span-2 xv2-kv"><div><span>${L('Suggested nodes','نودهای پیشنهادی')}</span><b>${xesc(nodes.map(n=>n.name||n.id).join(', ')||'—')}</b></div><div><span>${L('Target regions','ریجن هدف')}</span><b>USA · Germany</b></div></div><div class="span-2 xv2-actions"><button type="button" class="btn btn-primary" data-act="xv7smartoutpreview">${icon('activity')}${L('Preview Smart WARP','پیش‌نمایش Smart WARP')}</button></div><div class="span-2 notice">${L('No setting is saved and Xray is not restarted from this control.','از این کنترل هیچ تنظیمی ذخیره و Xray ری‌استارت نمی‌شود.')}</div></div></article>`;}
function outbounds(d){let list=Array.isArray(d.outbounds)?d.outbounds:[];return `<div class="xv2-grid">${smartWarpOutboundCard(d)}<article class="panel xv2-card" style="grid-column:1/-1"><div class="xv2-toolbar"><div><h3>${L('Outbounds','اوتباندها')}</h3><p>${L('Guided protocol forms for normal use; raw JSON stays available only under Advanced.','فرم هدایت‌شده برای استفاده عادی؛ JSON خام فقط در بخش پیشرفته باقی می‌ماند.')}</p></div><div class="spacer"></div>${button(L('Import link','Import لینک'),'xv3outimport','download')}${button(L('New outbound','اوتباند جدید'),'xv2outnew','plus','',true)}</div><div class="xv2-list">${list.map(outboundItem).join('')}</div></article></div>`;}
function targetLabel(r){return r.outboundTag?`OUT → ${r.outboundTag}`:`BAL → ${r.balancerTag||'—'}`;}
function smartRoutingCard(d){const p=d.smart||{},wn=p.nodes?.warp_ai?.nodes||[],an=p.nodes?.adblock?.nodes||[],wc=warpCandidates(d),active=p.activeStage7Rules||[],warpOn=active.some(r=>r.ruleTag==='dark-smart-warp-ai'),adsOn=active.some(r=>r.ruleTag==='dark-smart-adblock'),blockReady=(d.outbounds||[]).some(o=>o.tag==='block'&&o.protocol==='blackhole');return `${xcard(L('Smart WARP AI','وارپ هوشمند AI'),L('USA + Germany candidate nodes with leastPing/Observatory planning.','نودهای کاندید آمریکا + آلمان با برنامه leastPing/Observatory.'),`<div class="xv2-kv"><div><span>${L('Status','وضعیت')}</span><b>${warpOn?L('Configured','تنظیم‌شده'):L('Preview only','فقط پیش‌نمایش')}</b></div><div><span>${L('WARP paths','مسیرهای WARP')}</span><b>${xesc(wc.map(x=>x.tag).join(', ')||'—')}</b></div><div><span>${L('Suggested nodes','نودهای پیشنهادی')}</span><b>${xesc(wn.map(x=>x.name||x.id).join(', ')||'—')}</b></div></div><div class="xv2-actions" style="margin-top:12px">${button(L('Configure / Preview','تنظیم / پیش‌نمایش'),'xv7smartpreview','activity','',true)}</div>`)}${xcard(L('Smart Adblock','حذف تبلیغات هوشمند'),L('France + UK candidate nodes; uses the existing block outbound.','نودهای کاندید فرانسه + انگلیس؛ از Outbound فعلی block استفاده می‌کند.'),`<div class="xv2-kv"><div><span>${L('Status','وضعیت')}</span><b>${adsOn?L('Configured','تنظیم‌شده'):L('Preview only','فقط پیش‌نمایش')}</b></div><div><span>${L('Block outbound','اوتباند Block')}</span><b>${blockReady?L('Ready','آماده'):L('Missing','وجود ندارد')}</b></div><div><span>${L('Suggested nodes','نودهای پیشنهادی')}</span><b>${xesc(an.map(x=>x.name||x.id).join(', ')||'—')}</b></div></div><div class="xv2-actions" style="margin-top:12px">${button(L('Configure / Preview','تنظیم / پیش‌نمایش'),'xv7smartpreview','shield','',true)}</div>`)}<article class="panel xv2-card" style="grid-column:1/-1"><div class="notice">${L('Preview, Validate and Review do not change traffic. Apply is explicit, revision-fenced and keeps a rollback snapshot.','Preview، Validate و Review ترافیک را تغییر نمی‌دهند. Apply صریح است و Snapshot برگشت نگه می‌دارد.')}</div></article>`;}
function smartRoutingRevisionCard(d){const r=(d.smartRevisions||[])[0];if(!r)return xcard(L('Reviewed changes','تغییرات بررسی‌شده'),L('Validated snapshots appear here before any traffic change.','Snapshotهای اعتبارسنجی‌شده قبل از هر تغییر ترافیک اینجا نمایش داده می‌شوند.'),`<div class="notice">${L('No Smart Routing review snapshot yet.','هنوز Snapshot بررسی Smart Routing ساخته نشده است.')}</div>`);const state=String(r.state||'—'),short=String(r.revisionId||'').slice(0,12),roles=r.nodeRoles||{},report=r.safetyReport||{},issues=Array.isArray(report.issues)?report.issues:[],safety=r.safetyPassed?L('PASS · ready to apply','PASS · آماده اعمال'):r.safetyCheckedAt?L('BLOCKED / expired','BLOCKED / منقضی'):L('Not checked','بررسی نشده');let actions='';if(state==='reviewed'){actions=button(r.safetyPassed?L('Re-run Safety Gate','اجرای دوباره Safety Gate'):L('Run Safety Gate','اجرای Safety Gate'),'xv7smartsafety','shield',`data-revision="${xesc(r.revisionId)}"`,true)+(r.safetyPassed?button(L('Start staged rollout','شروع rollout مرحله‌ای'),'xv7smartrollout','activity',`data-revision="${xesc(r.revisionId)}"`,true):'')+button(L('Discard review','لغو Review'),'xv7smartrollback','trash',`data-revision="${xesc(r.revisionId)}"`);}else if(state==='applied')actions=button(L('Rollback','بازگردانی'),'xv7smartrollback','refresh',`data-revision="${xesc(r.revisionId)}"`,true);return xcard(L('Reviewed changes','تغییرات بررسی‌شده'),L('Apply stays locked until the live Safety Gate passes.','تا زمان PASS شدن Safety Gate زنده، Apply قفل می‌ماند.'),`<div class="xv2-kv"><div><span>${L('Revision','Revision')}</span><b class="mono">${xesc(short||'—')}</b></div><div><span>${L('State','وضعیت')}</span><b>${xesc(state)}</b></div><div><span>Safety Gate</span><b>${xesc(safety)}</b></div><div><span>WARP Nodes</span><b>${xesc((roles.warpNodeIds||[]).join(', ')||'—')}</b></div><div><span>Adblock Nodes</span><b>${xesc((roles.adblockNodeIds||[]).join(', ')||'—')}</b></div></div>${actions?`<div class="xv2-actions" style="margin-top:12px">${actions}</div>`:''}${issues.length?`<div class="notice warning" style="margin-top:12px">${xesc(issues.slice(0,3).join(' · '))}</div>`:''}<div class="notice" style="margin-top:12px">${xesc(r.detail||'')}</div>`);}
function smartRoutingRolloutCard(d){const r=(d.smartRollouts||[])[0];if(!r)return '';const items=r.items||[],rows=items.map(x=>`<div class="xv2-item"><div><b>${xesc(x.node_id)}</b><br><small>${xesc(x.role||'node')}</small></div><span>${xesc(x.state||'pending')}</span></div>`).join(''),hub=r.phase==='complete'?L('Healthy / applied last','سالم / آخر اعمال شد'):r.phase==='hub'?L('Applying last','در حال اعمال در آخر'):L('Waiting','در انتظار'),running=r.state==='running',paused=['paused','pause_requested'].includes(r.controlState),controls=running?(paused?button(L('Resume','ادامه'),'xv7rolloutresume','activity',`data-rollout="${xesc(r.rolloutId)}"`,true):button(L('Pause','توقف موقت'),'xv7rolloutpause','pause',`data-rollout="${xesc(r.rolloutId)}"`))+button(L('Abort + Rollback','لغو + بازگردانی'),'xv7rolloutabort','trash',`data-rollout="${xesc(r.rolloutId)}"`,true)+button(L('Timeline','تایم‌لاین'),'xv7rollouttimeline','activity',`data-rollout="${xesc(r.rolloutId)}"`):button(L('Timeline','تایم‌لاین'),'xv7rollouttimeline','activity',`data-rollout="${xesc(r.rolloutId)}"`);return `<article class="panel xv2-card" style="grid-column:1/-1"><div class="xv2-toolbar"><div><h3>${L('Staged rollout progress','پیشرفت rollout مرحله‌ای')}</h3><p>${L('Canary → Verify → Batch → Hub last. Any failed Node triggers automatic rollback.','Canary → Verify → Batch → Hub آخر. خرابی هر Node باعث rollback خودکار می‌شود.')}</p></div><span class="tag ${r.state==='completed'?'green':r.state==='running'?'amber':'red'}">${xesc(r.state)}</span></div><div class="xv2-kv"><div><span>${L('Phase','مرحله')}</span><b>${xesc(r.phase||'—')}</b></div><div><span>${L('Progress','پیشرفت')}</span><b>${xesc(r.progressPercent||0)}%</b></div><div><span>Hub</span><b>${xesc(hub)}</b></div><div><span>${L('Observation','پایش')}</span><b>${xesc(r.observationSeconds||5)}s / Node</b></div><div><span>${L('Healthy Nodes','Nodeهای سالم')}</span><b>${xesc(r.healthyNodes||0)} / ${xesc(r.totalNodes||0)}</b></div></div><div class="xv2-list" style="margin-top:12px">${rows||`<div class="notice">${L('No Node step is required; Hub-only rollout.','مرحله Node لازم نیست؛ rollout فقط Hub است.')}</div>`}</div><div class="xv2-actions" style="margin-top:12px">${controls}</div><div class="notice" style="margin-top:12px">${xesc(r.detail||'')}</div></article>`;}
function smartRoutingHistoryCard(d){const history=(d.smartRollouts||[]).slice(1,9);if(!history.length)return '';const rows=history.map(r=>`<div class="xv2-item"><div><b class="mono">${xesc(String(r.rolloutId||'').slice(0,10))}</b><br><small>${xesc(r.phase||'—')} · ${xesc(r.healthyNodes||0)}/${xesc(r.totalNodes||0)} Nodes</small></div><div><span class="tag ${r.state==='completed'?'green':r.state==='running'?'amber':'red'}">${xesc(r.state||'—')}</span> ${button(L('Timeline','تایم‌لاین'),'xv7rollouttimeline','activity',`data-rollout="${xesc(r.rolloutId)}"`)}</div><small>${xesc(r.detail||'')}</small></div>`).join('');return `<article class="panel xv2-card" style="grid-column:1/-1"><h3>${L('Rollout history','تاریخچه Rollout')}</h3><p>${L('Recent completed, aborted and rolled-back Smart Routing changes.','تغییرات اخیر Smart Routing شامل موفق، لغوشده و بازگردانی‌شده.')}</p><div class="xv2-list">${rows}</div></article>`;}
function smart(d){
 const p=d.smart||{},paths=warpCandidates(d),nodes=Array.isArray(p.nodeCandidates)?p.nodeCandidates:[],roles=p.nodeRoles||{},active=p.activeStage7Rules||[],revisions=d.smartRevisions||[],rollouts=d.smartRollouts||[];
 const warpOn=active.some(r=>r.ruleTag==='dark-smart-warp-ai'),adsOn=active.some(r=>r.ruleTag==='dark-smart-adblock'),blockReady=(d.outbounds||[]).some(o=>o.tag==='block'&&o.protocol==='blackhole');
 const online=nodes.filter(n=>n.online),warpAssigned=(roles.warpNodeIds||[]).length,adAssigned=(roles.adblockNodeIds||[]).length,latest=revisions[0]||null,rollout=rollouts[0]||null;
 const warpState=warpOn?L('Active','فعال'):paths.length?L('Ready to configure','آماده تنظیم'):L('Needs a WARP path','نیاز به مسیر WARP');
 const adsState=adsOn?L('Active','فعال'):blockReady?L('Ready to configure','آماده تنظیم'):L('Needs Block outbound','نیاز به Block outbound');
 let next='';
 if(latest&&latest.state==='reviewed'){
   const passed=!!latest.safetyPassed;
   next=`<article class="panel smart-next"><div><small>${L('NEXT ACTION','قدم بعدی')}</small><h3>${passed?L('Ready for safe activation','آماده فعال‌سازی امن'):L('Run the safety check','بررسی ایمنی را اجرا کن')}</h3><p>${passed?L('The reviewed setup passed live checks. Activate it gradually; DARK rolls back automatically if a Node fails.','تنظیم بررسی‌شده تست‌های زنده را پاس کرده؛ فعال‌سازی مرحله‌ای انجام می‌شود و در خطا rollback خودکار داریم.'):L('Your setup is saved as a review only. No traffic has changed yet.','تنظیم فقط به‌صورت Review ذخیره شده و هنوز هیچ ترافیکی تغییر نکرده است.')}</p></div><div class="xv2-actions">${passed?button(L('Activate safely','فعال‌سازی امن'),'xv7smartrollout','activity',`data-revision="${xesc(latest.revisionId)}"`,true):button(L('Run safety check','اجرای بررسی ایمنی'),'xv7smartsafety','shield',`data-revision="${xesc(latest.revisionId)}"`,true)}${button(L('Discard','لغو'),'xv7smartrollback','trash',`data-revision="${xesc(latest.revisionId)}"`)}</div></article>`;
 }
 return `<div class="smart-hub">
 <article class="panel smart-hero"><div><span class="smart-eyebrow">DARK SMART NETWORK</span><h2>${L('WARP and Adblock without Routing complexity','وارپ و حذف تبلیغات بدون پیچیدگی Routing')}</h2><p>${L('Choose what you want, pick Nodes, scan the real WARP path, then let DARK validate and activate it safely.','فقط قابلیت را انتخاب کن، نودها را مشخص کن، مسیر واقعی WARP را اسکن کن و بقیه بررسی و فعال‌سازی امن را به DARK بسپار.')}</p></div><div class="xv2-actions">${button(L('Start simple setup','شروع تنظیم ساده'),'xv7smartpreview','activity','',true)}${paths.length?button(L('Scan WARP paths','اسکن مسیرهای WARP'),'xv7warpscan','activity'):button(L('Create WARP path','ساخت مسیر WARP'),'xv7gotooutbounds','arrow')}</div></article>
 <div class="smart-status-grid">
  <article class="panel smart-feature-card"><div class="smart-feature-head"><div><small>AI TRAFFIC</small><h3>Smart WARP</h3></div><span class="tag ${warpOn?'green':paths.length?'amber':'red'}">${xesc(warpState)}</span></div><p>${paths.length?L('WARP paths are available. Select the Nodes that should carry AI traffic.','مسیر WARP موجود است؛ نودهایی که باید ترافیک AI را حمل کنند انتخاب کن.'):L('No WireGuard/WARP path exists yet. Create it once in Xray → Outbounds; after that, everything is managed here.','هنوز مسیر WireGuard/WARP نداریم. یک‌بار در Xray → Outbounds آن را بساز؛ بعد از آن همه‌چیز از همین صفحه مدیریت می‌شود.')}</p><div class="smart-mini-kv"><span>${L('Paths','مسیرها')} <b>${paths.length}</b></span><span>${L('Assigned Nodes','نودهای انتخاب‌شده')} <b>${warpAssigned}</b></span></div></article>
  <article class="panel smart-feature-card"><div class="smart-feature-head"><div><small>DNS / DOMAIN RULES</small><h3>Smart Adblock</h3></div><span class="tag ${adsOn?'green':blockReady?'amber':'red'}">${xesc(adsState)}</span></div><p>${L('Adblock uses DARK-managed rules and the Block outbound. You choose which Nodes should handle it.','حذف تبلیغات از Ruleهای مدیریت‌شده DARK و Block outbound استفاده می‌کند؛ فقط نودهای موردنظر را انتخاب می‌کنی.')}</p><div class="smart-mini-kv"><span>Block <b>${blockReady?L('Ready','آماده'):L('Missing','ندارد')}</b></span><span>${L('Assigned Nodes','نودهای انتخاب‌شده')} <b>${adAssigned}</b></span></div></article>
  <article class="panel smart-feature-card"><div class="smart-feature-head"><div><small>INFRASTRUCTURE</small><h3>${L('Nodes','نودها')}</h3></div><span class="tag ${online.length?'green':'red'}">${online.length}/${nodes.length} ${L('online','آنلاین')}</span></div><p>${L('Only healthy enabled Nodes are used. Region suggestions are guidance, not a hidden requirement.','فقط نودهای فعال و سالم استفاده می‌شوند؛ پیشنهاد ریجن راهنماست و محدودیت مخفی نیست.')}</p><div class="xv2-actions">${button(L('Manage Nodes','مدیریت نودها'),'xv7gotonodes','server')}</div></article>
 </div>
 <article class="panel smart-flow"><div class="smart-flow-head"><div><small>${L('HOW IT WORKS','روند کار')}</small><h3>${L('Four simple steps','چهار قدم ساده')}</h3></div><span>${L('No traffic changes before the final activation.','تا مرحله آخر هیچ ترافیکی تغییر نمی‌کند.')}</span></div><div class="smart-steps"><div><b>1</b><span><strong>${L('Choose feature','انتخاب قابلیت')}</strong><small>WARP / Adblock</small></span></div><div><b>2</b><span><strong>${L('Choose Nodes','انتخاب نود')}</strong><small>${L('where it should run','محل اجرا')}</small></span></div><div><b>3</b><span><strong>${L('Scan & safety check','اسکن و بررسی ایمنی')}</strong><small>${L('real path health','سلامت واقعی مسیر')}</small></span></div><div><b>4</b><span><strong>${L('Safe activation','فعال‌سازی امن')}</strong><small>${L('gradual + auto rollback','مرحله‌ای + rollback خودکار')}</small></span></div></div></article>
 ${!paths.length?`<article class="panel smart-blocker"><div><b>${L('Smart WARP is not ready yet','Smart WARP هنوز آماده نیست')}</b><p>${L('The only missing piece is a real WireGuard/WARP outbound. Create one under Xray Settings → Outbounds; this page will detect it automatically.','فقط یک مسیر واقعی WireGuard/WARP کم است. آن را از تنظیمات Xray → Outbounds بساز؛ این صفحه خودکار آن را شناسایی می‌کند.')}</p></div>${button(L('Open Xray Outbounds','رفتن به Outbounds'),'xv7gotooutbounds','arrow','',true)}</article>`:''}
 ${next}
 <details class="panel smart-advanced"><summary>${L('Advanced details & rollout history','جزئیات حرفه‌ای و تاریخچه فعال‌سازی')}</summary><div class="xv2-grid">${smartRoutingRevisionCard(d)}${smartRoutingRolloutCard(d)}${smartRoutingHistoryCard(d)}</div></details>
 </div>`;}
function routing(d){let v=d.routing||{},rules=Array.isArray(v.rules)?v.rules:[];return `<div class="xv2-grid">${smartRoutingCard(d)}${smartRoutingRevisionCard(d)}${smartRoutingRolloutCard(d)}${smartRoutingHistoryCard(d)}${xcard(L('Routing engine','موتور روتینگ'),' ',`<div class="xv2-kv"><div><span>domainStrategy</span><b>${xesc(v.domainStrategy||'AsIs')}</b></div><div><span>${L('Rules','قواعد')}</span><b>${rules.length}</b></div></div><div class="xv2-actions" style="margin-top:12px">${button(L('Routing settings','تنظیمات روتینگ'),'xv2routesettings','settings')}</div>`)}${xcard(L('Rule order','ترتیب قواعد'),L('Top to bottom equals Xray evaluation order.','ترتیب بالا به پایین همان ترتیب اجرای Xray است.'),button(L('Add rule','افزودن Rule'),'xv2rulenew','plus','',true))}<article class="panel xv2-card" style="grid-column:1/-1"><div class="xv2-list">${rules.length?rules.map((r,i)=>`<div class="xv2-item xv2-rule"><div><b>#${i+1}</b> <span class="xv2-route-target">${xesc(targetLabel(r))}</span></div><div><small>${xesc([...(r.domain||[]),...(r.ip||[]),...(r.inboundTag||[]),r.port||'',r.network||'',r.protocol||''].filter(Boolean).join(' · ')||L('Catch-all field rule','Rule بدون شرط'))}</small></div><div class="xv2-actions">${button('↑','xv2ruleup','arrow',`data-index="${i}"`)}${button('↓','xv2ruledown','arrow',`data-index="${i}"`)}${button(L('Edit','ویرایش'),'xv2ruleedit','edit',`data-index="${i}"`)}${button(L('Delete','حذف'),'xv2ruledelete','trash',`data-index="${i}"`)}</div></div>`).join(''):empty(L('No routing rules.','Rule روتینگ وجود ندارد.'))}</div></article></div>`;}
function balancers(d){let v=d.routing||{},bs=Array.isArray(v.balancers)?v.balancers:[];return `<div class="xv2-grid"><article class="panel xv2-card" style="grid-column:1/-1"><div class="xv2-toolbar"><div><h3>${L('Balancers','بالانسرها')}</h3><p>${L('Native Xray balancers stored inside routing.','بالانسرهای بومی Xray داخل Routing ذخیره می‌شوند.')}</p></div><div class="spacer"></div>${button(L('New balancer','بالانسر جدید'),'xv2balnew','plus','',true)}</div><div class="xv2-list">${bs.length?bs.map((b,i)=>`<div class="xv2-item"><div class="xv2-item-head"><div><b>${xesc(b.tag)}</b><small> · ${xesc(b.strategy?.type||'random')}</small><div class="xv2-balance">${(b.selector||[]).map(x=>`<span>${xesc(x)}</span>`).join('')}</div>${b.fallbackTag?`<small>fallback → ${xesc(b.fallbackTag)}</small>`:''}</div><div class="xv2-actions">${button(L('Edit','ویرایش'),'xv2baledit','edit',`data-index="${i}"`)}${button(L('Delete','حذف'),'xv2baldelete','trash',`data-index="${i}"`)}</div></div></div>`).join(''):empty(L('No balancers.','بالانسری وجود ندارد.'))}</div></article></div>`;}
function observatory(d){let o=d.observatory||{};return `<div class="xv2-grid">${xcard('Observatory',L('Outbound health observation configuration.','تنظیمات پایش سلامت Outbound.'),`<div class="xv2-kv"><div><span>subjectSelector</span><b>${xesc((o.subjectSelector||[]).join(', ')||'—')}</b></div><div><span>probeURL</span><b class="mono">${xesc(o.probeURL||'—')}</b></div><div><span>probeInterval</span><b>${xesc(o.probeInterval||'—')}</b></div><div><span>enableConcurrency</span><b>${String(!!o.enableConcurrency)}</b></div></div><div class="xv2-actions" style="margin-top:12px">${button(L('Edit observatory','ویرایش Observatory'),'xv2obsedit','edit','',true)}</div>`)}</div>`;}
function advanced(d){return `<div class="xv2-grid">${['dns','outbounds','routing','policy','observatory'].map(k=>xcard(k.toUpperCase(),L('Advanced JSON editor for this section.','ویرایشگر JSON پیشرفته این بخش.'),button(L('Open JSON','بازکردن JSON'),'sectionedit','terminal',`data-section="${k}"`))).join('')}</div>`;}
enginePage=async function(){if(!['xray','outbounds','routing','smart'].includes(state.page))return baseEnginePage();const d=await allData();if(state.page==='smart')return heading(L('Smart Network','شبکه هوشمند'),L('Simple WARP and Adblock control. Technical Xray settings stay under Xray Settings.','مدیریت ساده WARP و حذف تبلیغات؛ تنظیمات فنی Xray داخل تنظیمات Xray باقی می‌مانند.'))+`<div class="xv2">${smart(d)}</div>`;if(state.page==='outbounds')state.xv2.tab='outbounds';if(state.page==='routing')state.xv2.tab='routing';let body={general,dns,outbounds,routing,balancers,observatory,advanced}[state.xv2.tab](d);return heading('Xray Control',L('Structured local Xray settings with DARK validation boundaries.','تنظیمات ساختاریافته Xray محلی با مرزهای اعتبارسنجی DARK.'))+`<div class="xv2">${xtabs()}${body}</div>`;};
async function saveSection(name,value){await api('/api/settings/'+name,'PUT',{value});toast(L('Saved in DARK. Validate before apply.','در DARK ذخیره شد؛ قبل از اعمال Validate کن.'));await refresh();}
async function editDNS(){let d=(await api('/api/settings/dns')).value||{};dialog(L('DNS settings','تنظیمات DNS'),`<div class="xv2-form">${field('queryStrategy','queryStrategy',d.queryStrategy||'UseIP')}${field('tag','tag',d.tag||'')}${select('disableCache','disableCache',[['false','false'],['true','true']],String(!!d.disableCache))}<label class="span-2">${L('Servers — one string per line or JSON object','Servers — هر خط یک مقدار یا JSON')}<textarea class="xv2-textarea" name="servers">${xesc((d.servers||[]).map(x=>typeof x==='string'?x:JSON.stringify(x)).join('\n'))}</textarea></label></div>`,async f=>{let servers=String(f.get('servers')||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map(x=>{if(x.startsWith('{')){try{return JSON.parse(x);}catch{throw Error('Invalid DNS server JSON');}}return x;});let v={...d,servers,queryStrategy:f.get('queryStrategy'),disableCache:f.get('disableCache')==='true'};if(f.get('tag'))v.tag=f.get('tag');else delete v.tag;await saveSection('dns',v);closeDialog();});}
async function editOutbound(index=null,clone=false){let list=(await api('/api/settings/outbounds')).value||[],o=index==null?{tag:'proxy',protocol:'freedom',settings:{},streamSettings:{sockopt:{}}}:JSON.parse(JSON.stringify(list[index]));if(clone)o.tag=(o.tag||'out')+'-copy';dialog(index==null?L('New outbound','اوتباند جدید'):L('Edit outbound','ویرایش اوتباند'),`<div class="xv2-form">${field('Tag','tag',o.tag||'','text','required pattern="[A-Za-z0-9_.-]+"')}${field('Protocol','protocol',o.protocol||'freedom','text','required')}${field('Chained via tag','dialerProxy',o.streamSettings?.sockopt?.dialerProxy||'')}<label class="span-2">Settings JSON<textarea class="xv2-textarea" name="settings">${xesc(JSON.stringify(o.settings||{},null,2))}</textarea></label><label class="span-2">StreamSettings JSON<textarea class="xv2-textarea" name="stream">${xesc(JSON.stringify(o.streamSettings||{},null,2))}</textarea></label></div>`,async f=>{let settings,stream;try{settings=JSON.parse(f.get('settings'));stream=JSON.parse(f.get('stream'));}catch{throw Error('Invalid JSON');}stream.sockopt=stream.sockopt||{};if(f.get('dialerProxy'))stream.sockopt.dialerProxy=f.get('dialerProxy');else delete stream.sockopt.dialerProxy;let v={...o,tag:f.get('tag'),protocol:f.get('protocol'),settings,streamSettings:stream};if(index==null||clone)list.push(v);else list[index]=v;await saveSection('outbounds',list);closeDialog();});}
async function showSmartRoutingReview(body){const r=await api('/api/smart-routing/preview','POST',body),rules=r.routing?.rules||[],warnings=r.warnings||[],roles=r.nodeRoles||{},summary={rules:rules.filter(x=>String(x.ruleTag||'').startsWith('dark-smart-')),balancers:(r.routing?.balancers||[]).filter(x=>x.tag==='dark-smart-warp-ai-balancer'),observatory:r.observatory};closeDialog();dialog(L('Review before saving','بررسی قبل از ذخیره'),`<div class="smart-review"><div class="notice ok"><b>${L('Nothing is live yet','هنوز چیزی فعال نشده')}</b><br>${L('This step only validates the plan and prepares a rollback-safe review.','این مرحله فقط تنظیمات را بررسی می‌کند و یک Review امن برای بازگشت می‌سازد.')}</div><div class="smart-review-grid"><div><span>Smart WARP</span><b>${body.warpAi?L('Enabled in plan','در برنامه فعال'):L('Off','خاموش')}</b><small>${(body.warpOutboundTags||[]).length} ${L('path(s)','مسیر')}</small></div><div><span>Smart Adblock</span><b>${body.adblock?L('Enabled in plan','در برنامه فعال'):L('Off','خاموش')}</b><small>${(roles.adblockNodeIds||[]).length} ${L('Node(s)','نود')}</small></div><div><span>${L('WARP Nodes','نودهای WARP')}</span><b>${(roles.warpNodeIds||[]).length}</b><small>${L('selected','انتخاب‌شده')}</small></div></div>${warnings.length?`<div class="notice warning"><b>${L('Needs attention','نیاز به توجه')}</b><br>${xesc(warnings.join(' · '))}</div>`:''}<details class="smart-technical"><summary>${L('Technical preview','پیش‌نمایش فنی')}</summary><pre class="xv2-textarea" style="white-space:pre-wrap;max-height:38vh;overflow:auto">${xesc(JSON.stringify(summary,null,2))}</pre></details></div>`,async()=>{const v=await api('/api/smart-routing/validate','POST',body);const reviewed=await api('/api/smart-routing/review','POST',{...body,baselineHash:v.baselineHash,candidateHash:v.candidateHash,confirmation:'REVIEW SMART ROUTING'});closeDialog();toast(L('Setup saved for safety check. Production traffic is unchanged.','تنظیم برای بررسی ایمنی ذخیره شد؛ ترافیک Production هنوز تغییر نکرده است.'));state.page='smart';await refresh();return reviewed;},L('Save for safety check','ذخیره برای بررسی ایمنی'));}
async function smartRoutingPreview(){
 const plan=await api('/api/smart-routing/plan'),outs=(await api('/api/settings/outbounds')).value||[];
 const planned=Array.isArray(plan.warpCandidates)?plan.warpCandidates:[],candidates=planned.length?planned:outs.filter(o=>o.protocol==='wireguard').map(o=>({tag:o.tag,node:o.tag,region:'—',likelyWarp:true})),blockReady=outs.some(o=>o.tag==='block'&&o.protocol==='blackhole');
 const preferred=new Set(plan.configuredWarpCandidates||[]),paths=candidates.map((c,i)=>`<label class="smart-path"><input type="checkbox" name="warpOutboundTags" value="${xesc(c.tag)}" ${(preferred.has(c.tag)||(!preferred.size&&(c.likelyWarp||i<2)))?'checked':''}><span><b>${xesc(c.tag)}</b><small>${xesc(c.node||c.tag)} · ${xesc(c.region||'—')}</small></span></label>`).join('');
 const rolePolicy=plan.nodeRoles||{},nodeRows=Array.isArray(plan.nodeCandidates)?plan.nodeCandidates:[],warpSuggested=new Set((plan.nodes?.warp_ai?.nodes||[]).map(x=>String(x.id))),adSuggested=new Set((plan.nodes?.adblock?.nodes||[]).map(x=>String(x.id)));
 const warpSelected=new Set((rolePolicy.warpNodeIds||[]).length?(rolePolicy.warpNodeIds||[]).map(String):[...warpSuggested]),adSelected=new Set((rolePolicy.adblockNodeIds||[]).length?(rolePolicy.adblockNodeIds||[]).map(String):[...adSuggested]);
 const roleRows=nodeRows.map(n=>`<div class="smart-node-row"><div><b>${xesc(n.name||n.id)}</b><small>${n.online?L('Online','آنلاین'):L('Offline','آفلاین')} · <span class="mono">${xesc(n.data_address||n.id)}</span></small></div><div><label><input type="checkbox" name="warpNodeIds" value="${xesc(n.id)}" ${warpSelected.has(String(n.id))?'checked':''} ${candidates.length?'':'disabled'}> WARP</label><label><input type="checkbox" name="adblockNodeIds" value="${xesc(n.id)}" ${adSelected.has(String(n.id))?'checked':''} ${blockReady?'':'disabled'}> Adblock</label></div></div>`).join('')||`<div class="notice warning">${L('No enabled Nodes are registered.','هیچ Node فعالی ثبت نشده است.')}</div>`;
 dialog(L('Smart Network setup','تنظیم شبکه هوشمند'),`<div class="smart-setup"><section><div class="smart-step-title"><b>1</b><span><strong>${L('Choose what to enable','انتخاب قابلیت')}</strong><small>${L('Unavailable features stay disabled until their requirement exists.','قابلیت‌های ناقص تا آماده‌شدن پیش‌نیاز غیرفعال می‌مانند.')}</small></span></div><div class="smart-choice-grid"><label class="smart-choice ${candidates.length?'':'disabled'}"><input type="checkbox" name="warpAi" ${candidates.length?'checked':'disabled'}><span><b>Smart WARP</b><small>${candidates.length?L('Ready to configure','آماده تنظیم'):L('Create a WARP path first','اول مسیر WARP بساز')}</small></span></label><label class="smart-choice ${blockReady?'':'disabled'}"><input type="checkbox" name="adblock" ${blockReady?'checked':'disabled'}><span><b>Smart Adblock</b><small>${blockReady?L('Ready to configure','آماده تنظیم'):L('Block outbound is missing','Block outbound وجود ندارد')}</small></span></label></div></section><section><div class="smart-step-title"><b>2</b><span><strong>${L('Choose Nodes','انتخاب نودها')}</strong><small>${L('Pick where each feature should run.','مشخص کن هر قابلیت روی کدام نود اجرا شود.')}</small></span></div><div class="smart-node-list">${roleRows}</div></section><section><div class="smart-step-title"><b>3</b><span><strong>${L('Choose WARP paths','انتخاب مسیرهای WARP')}</strong><small>${L('You can scan them from the Smart WARP page before activation.','قبل از فعال‌سازی می‌توانی از صفحه Smart WARP مسیرها را اسکن کنی.')}</small></span></div><div class="smart-path-list">${paths||`<div class="notice warning">${L('No WARP path exists. Go to Xray Settings → Outbounds and create a WireGuard/WARP path first.','هیچ مسیر WARP وجود ندارد. ابتدا از تنظیمات Xray → Outbounds یک مسیر WireGuard/WARP بساز.')}</div>`}</div></section><div class="notice">${L('Saving this setup does not change production traffic. The next step is a live safety check.','ذخیره این تنظیم هیچ تغییری در ترافیک Production ایجاد نمی‌کند؛ قدم بعدی بررسی ایمنی زنده است.')}</div></div>`,async f=>{const warpAi=f.get('warpAi')==='on',adblock=f.get('adblock')==='on';if(!warpAi&&!adblock)throw Error(L('Choose at least one feature.','حداقل یک قابلیت را انتخاب کن.'));const warpOutboundTags=f.getAll('warpOutboundTags').map(String);if(warpAi&&!warpOutboundTags.length)throw Error(L('Select at least one WARP path.','حداقل یک مسیر WARP انتخاب کن.'));await showSmartRoutingReview({warpAi,adblock,warpOutboundTags,warpNodeIds:f.getAll('warpNodeIds').map(String),adblockNodeIds:f.getAll('adblockNodeIds').map(String)});},L('Review setup','بررسی تنظیمات'));
}
async function scanSmartWarpPage(){const plan=await api('/api/smart-routing/plan'),tags=(plan.warpCandidates||[]).map(x=>String(x.tag||'')).filter(Boolean).slice(0,8);if(!tags.length)throw Error(L('No WARP path exists yet. Create one in Xray Settings → Outbounds.','هنوز مسیر WARP وجود ندارد؛ ابتدا در تنظیمات Xray → Outbounds آن را بساز.'));toast(L('Scanning real WARP paths…','در حال اسکن واقعی مسیرهای WARP…'));const r=await api('/api/smart-routing/warp-scan','POST',{outboundTags:tags,attempts:2,timeoutSeconds:5}),items=r.items||[],rows=items.map((x,i)=>`<div class="smart-scan-row"><div><b>#${i+1} · ${xesc(x.tag||'—')}</b><small>${xesc(x.node||'—')} · ${xesc(x.region||'—')}</small></div><div><span>${x.latencyMs==null?'—':xesc(x.latencyMs)+' ms'}</span><span>${xesc(x.lossPercent??'—')}% loss</span><span>${xesc(x.jitterMs??'—')} ms jitter</span><b class="${x.ready?'ok-text':'warn-text'}">${x.ready?L('Ready','آماده'):L('Blocked','نامناسب')}</b></div></div>`).join('');dialog(L('WARP path scan','اسکن مسیرهای WARP'),`<div class="notice">${L('Paths are ranked from best to worst. This scan does not change production traffic.','مسیرها از بهترین به ضعیف‌ترین مرتب شده‌اند؛ این اسکن هیچ تغییری در ترافیک Production ایجاد نمی‌کند.')}</div><div class="smart-scan-list">${rows||'—'}</div>`,async()=>closeDialog(),L('Close','بستن'));return r;}
async function smartRoutingOutboundPreview(){const root=document.querySelector('#xv7-smart-outbound');if(!root)throw Error('Smart WARP controls unavailable');const warpAi=!!root.querySelector('input[name="warpAi"]')?.checked,tags=[...root.querySelectorAll('input[name="warpOutboundTags"]:checked')].map(x=>String(x.value));if(warpAi&&!tags.length)throw Error(L('Select at least one WARP outbound.','حداقل یک Outbound وارپ انتخاب کن.'));await showSmartRoutingReview({warpAi,adblock:false,warpOutboundTags:tags});}
async function runSmartSafety(id){if(!id)throw Error('Missing Smart Routing revision');toast(L('Checking Nodes and WARP paths…','در حال بررسی نودها و مسیرهای WARP…'));const r=await api('/api/smart-routing/safety-check','POST',{revisionId:id,attempts:3,timeoutSeconds:5,maxLossPercent:20,maxLatencyMs:1200,maxJitterMs:350}),s=r.safetyReport||{},nodes=s.nodeReadiness?.checks||[],paths=s.warpSafety?.items||[],issues=s.issues||[];const nodeRows=nodes.map(x=>`<div class="smart-check-row"><div><b>${xesc(x.name||x.nodeId)}</b><small>${xesc(x.role)}</small></div><span class="tag ${x.ready?'green':'red'}">${x.ready?L('Ready','آماده'):L('Problem','مشکل')}</span></div>`).join(''),pathRows=paths.map(x=>`<div class="smart-check-row"><div><b>${xesc(x.tag)}</b><small>${x.latencyMs==null?'—':xesc(x.latencyMs)+' ms'} · ${xesc(x.lossPercent)}% loss · ${xesc(x.jitterMs)} ms jitter</small></div><span class="tag ${x.ready?'green':'red'}">${x.ready?L('Ready','آماده'):L('Blocked','نامناسب')}</span></div>`).join('');dialog(L('Safety check','بررسی ایمنی'),`<div class="notice ${r.safetyPassed?'ok':'warning'}"><b>${r.safetyPassed?L('Everything looks good','همه‌چیز آماده است'):L('Activation is blocked','فعال‌سازی متوقف شد')}</b><br>${r.safetyPassed?L('This result is valid for 5 minutes. You can now activate safely.','این نتیجه ۵ دقیقه اعتبار دارد؛ حالا می‌توانی فعال‌سازی امن را شروع کنی.'):L('Fix the items below and run the check again. Production traffic was not changed.','موارد زیر را برطرف کن و دوباره تست بگیر؛ ترافیک Production تغییری نکرده است.')}</div><div class="smart-check-grid"><article><h3>${L('Nodes','نودها')}</h3>${nodeRows||'<span>—</span>'}</article><article><h3>${L('WARP paths','مسیرهای WARP')}</h3>${pathRows||'<span>—</span>'}</article></div>${issues.length?`<div class="notice warning"><b>${L('What needs fixing','موارد لازم برای اصلاح')}</b><br>${xesc(issues.join(' · '))}</div>`:''}`,async()=>{closeDialog();state.page='smart';await refresh();},L('Close','بستن'));}
function rolloutLiveHTML(r){const rows=(r.items||[]).map(x=>`<div class="xv2-item"><div><b>${xesc(x.node_id)}</b><br><small>${xesc(x.role||'node')}</small></div><span>${xesc(x.state||'pending')}</span></div>`).join(''),paused=['paused','pause_requested'].includes(r.controlState),controls=r.state==='running'?(paused?button(L('Resume','ادامه'),'xv7rolloutresume','activity',`data-rollout="${xesc(r.rolloutId)}"`,true):button(L('Pause','توقف موقت'),'xv7rolloutpause','pause',`data-rollout="${xesc(r.rolloutId)}"`))+button(L('Abort + Rollback','لغو + بازگردانی'),'xv7rolloutabort','trash',`data-rollout="${xesc(r.rolloutId)}"`,true)+button(L('Timeline','تایم‌لاین'),'xv7rollouttimeline','activity',`data-rollout="${xesc(r.rolloutId)}"`):button(L('Timeline','تایم‌لاین'),'xv7rollouttimeline','activity',`data-rollout="${xesc(r.rolloutId)}"`),telemetry=rolloutTimelineHTML((r.timeline||[]).slice(-6));return `<div class="notice ${r.state==='completed'?'ok':r.state==='running'?'':'warning'}"><b>${xesc(r.state||'—')}</b> · ${xesc(r.phase||'—')} · ${xesc(r.controlState||'run')} · ${xesc(r.progressPercent||0)}%</div><div class="xv2-list" style="margin-top:12px">${rows||`<div class="xv2-item"><b>Hub</b><span>${xesc(r.phase||'pending')}</span></div>`}</div><div class="xv2-actions" style="margin-top:12px">${controls}</div><div class="xv2-list" style="margin-top:12px;max-height:28vh;overflow:auto">${telemetry}</div><div class="notice" style="margin-top:12px">${xesc(r.detail||'')}</div>`;}
function rolloutEventText(ev){const m=ev.metrics||{};if(ev.kind==='health_sample')return `${ev.detail||'health'}${m.latencyMs!=null?' · '+m.latencyMs+'ms':''}${m.coreState?' · core '+m.coreState:''}`;if(ev.kind==='warp_probe'){const items=m.items||[],best=items[0]||{};return `${ev.detail||'WARP'} · ${m.passed?'PASS':'BLOCKED'}${best.latencyMs!=null?' · '+best.latencyMs+'ms':''}${best.lossPercent!=null?' · '+best.lossPercent+'% loss':''}${best.jitterMs!=null?' · '+best.jitterMs+'ms jitter':''}`;}return ev.detail||ev.kind||'event';}
function rolloutTimelineHTML(items){return (items||[]).slice().reverse().map(ev=>`<div class="xv2-item"><div><b>${xesc(ev.kind||'event')}</b>${ev.node_id?` <span class="tag">${xesc(ev.node_id)}</span>`:''}<br><small>${xesc(ev.phase||ev.state||'—')}</small></div><span>${xesc(rolloutEventText(ev))}</span></div>`).join('')||`<div class="notice">${L('No rollout telemetry yet.','هنوز داده‌ای برای rollout ثبت نشده است.')}</div>`;}
async function showRolloutTimeline(id){if(!id)throw Error('Missing rollout');const doc=await api('/api/smart-routing/rollout/'+id),items=doc.timeline||[];dialog(L('Rollout timeline & telemetry','تایم‌لاین و تله‌متری Rollout'),`<div class="notice"><b>${xesc(doc.state||'—')}</b> · ${xesc(doc.phase||'—')} · ${xesc(doc.controlState||'run')} · ${xesc(doc.progressPercent||0)}%</div><div class="xv2-list" style="margin-top:12px;max-height:58vh;overflow:auto">${rolloutTimelineHTML(items)}</div>`,async()=>closeDialog(),L('Close','بستن'));}
async function controlSmartRollout(id,action){if(!id)throw Error('Missing rollout');const meta={pause:['PAUSE STAGED ROLLOUT',L('Pause rollout at the next safe checkpoint?','Rollout در نزدیک‌ترین نقطه امن متوقف شود؟')],resume:['RESUME STAGED ROLLOUT',''],abort:['ABORT STAGED ROLLOUT',L('Abort rollout and restore every changed Node to baseline?','Rollout لغو و تمام Nodeهای تغییرکرده به baseline برگردند؟')]};const row=meta[action];if(!row)throw Error('Unknown rollout action');if(row[1]&&!confirm(row[1]))return;const r=await api('/api/smart-routing/rollout/'+id+'/'+action,'POST',{confirmation:row[0]});toast(action==='abort'?L('Abort requested; rollback is running.','Abort ثبت شد؛ rollback در حال اجراست.'):action==='pause'?L('Pause requested.','درخواست توقف ثبت شد.'):L('Rollout resumed.','Rollout ادامه یافت.'));await refresh();return r;}
async function startSmartRollout(id){if(!id)throw Error('Missing Smart Routing revision');if(!confirm(L('Activate this setup safely? DARK applies it one Node at a time and automatically rolls back if a health check fails.','این تنظیم به‌صورت امن فعال شود؟ DARK آن را نودبه‌نود اعمال می‌کند و اگر تست سلامت خطا بدهد خودکار برمی‌گرداند.')))return;let r=await api('/api/smart-routing/rollout/start','POST',{revisionId:id,confirmation:'START STAGED ROLLOUT',observationSeconds:5}),rolloutId=r.rolloutId;dialog(L('Safe activation','فعال‌سازی امن'),`<div data-xv7-rollout-live>${rolloutLiveHTML(r)}</div>`,async()=>closeDialog(),L('Close','بستن'));for(let i=0;i<240&&r.state==='running';i++){await new Promise(resolve=>setTimeout(resolve,500));r=await api('/api/smart-routing/rollout/'+rolloutId);const box=document.querySelector('[data-xv7-rollout-live]');if(box)box.innerHTML=rolloutLiveHTML(r);}if(r.state==='completed')toast(L('Safe activation completed.','فعال‌سازی امن با موفقیت کامل شد.'));else if(r.state!=='running')toast(L('Activation stopped and automatic rollback was completed.','فعال‌سازی متوقف شد و بازگشت خودکار انجام شد.'),true);await refresh();}
async function activateSmartRevision(id){if(!id)throw Error('Missing Smart Routing revision');if(!confirm(L('Apply this Safety-PASS reviewed Smart Routing revision? Xray may perform one controlled restart.','این Revision که Safety PASS شده اعمال شود؟ ممکن است Xray یک ری‌استارت کنترل‌شده انجام دهد.')))return;await api('/api/smart-routing/activate','POST',{revisionId:id,confirmation:'APPLY SMART ROUTING'});toast(L('Smart Routing applied. Rollback snapshot is available.','Smart Routing اعمال شد؛ Snapshot بازگشت آماده است.'));await refresh();}
async function rollbackSmartRevision(id){if(!id)throw Error('Missing Smart Routing revision');if(!confirm(L('Rollback/discard this Smart Routing revision?','این Revision بازگردانی/لغو شود؟')))return;await api('/api/smart-routing/rollback','POST',{revisionId:id,confirmation:'ROLLBACK SMART ROUTING'});toast(L('Smart Routing revision rolled back or discarded.','Revision Smart Routing بازگردانی یا لغو شد.'));await refresh();}

async function routeSettings(){let v=(await api('/api/settings/routing')).value||{};dialog(L('Routing settings','تنظیمات روتینگ'),`<div class="xv2-form">${field('domainStrategy','domainStrategy',v.domainStrategy||'AsIs')}<div class="span-2 notice">${L('Rules and balancers stay untouched.','Ruleها و Balancerها تغییر نمی‌کنند.')}</div></div>`,async f=>{v.domainStrategy=f.get('domainStrategy');await saveSection('routing',v);closeDialog();});}
function csv(v){return String(v||'').split(',').map(x=>x.trim()).filter(Boolean);}
async function editRule(index=null){let routing=(await api('/api/settings/routing')).value||{},rules=routing.rules||[],r=index==null?{type:'field',outboundTag:'direct'}:JSON.parse(JSON.stringify(rules[index]));dialog(index==null?L('New routing rule','Rule جدید'):L('Edit routing rule','ویرایش Rule'),`<div class="xv2-form">${field('Domains (comma separated)','domain',(r.domain||[]).join(','))}${field('IPs / GeoIP (comma separated)','ip',(r.ip||[]).join(','))}${field('Inbound tags','inboundTag',(r.inboundTag||[]).join(','))}${field('Port','port',r.port||'')}${field('Network','network',r.network||'')}${field('Protocol','protocol',r.protocol||'')}${field('Outbound tag','outboundTag',r.outboundTag||'')}${field('Balancer tag','balancerTag',r.balancerTag||'')}</div>`,async f=>{let x={type:'field'};for(const k of ['domain','ip','inboundTag']){let a=csv(f.get(k));if(a.length)x[k]=a;}for(const k of ['port','network','protocol','outboundTag','balancerTag']){let v=String(f.get(k)||'').trim();if(v)x[k]=v;}if(Boolean(x.outboundTag)===Boolean(x.balancerTag))throw Error(L('Choose exactly one outbound or balancer.','دقیقاً یکی از Outbound یا Balancer را انتخاب کن.'));if(index==null)rules.push(x);else rules[index]=x;routing.rules=rules;await saveSection('routing',routing);closeDialog();});}
async function mutateRule(index,mode){let v=(await api('/api/settings/routing')).value||{},rules=v.rules||[];if(mode==='delete')rules.splice(index,1);else{let j=mode==='up'?index-1:index+1;if(j<0||j>=rules.length)return;[rules[index],rules[j]]=[rules[j],rules[index]];}v.rules=rules;await saveSection('routing',v);}
async function editBalancer(index=null){let v=(await api('/api/settings/routing')).value||{},bs=v.balancers||[],b=index==null?{tag:'balance',selector:['proxy'],strategy:{type:'random'}}:JSON.parse(JSON.stringify(bs[index]));dialog(index==null?L('New balancer','بالانسر جدید'):L('Edit balancer','ویرایش بالانسر'),`<div class="xv2-form">${field('Tag','tag',b.tag||'','text','required')}${field('Selectors (comma separated)','selector',(b.selector||[]).join(','),'text','required')}${field('Strategy type','strategy',b.strategy?.type||'random')}${field('Fallback tag','fallbackTag',b.fallbackTag||'')}</div>`,async f=>{let x={tag:f.get('tag'),selector:csv(f.get('selector')),strategy:{type:f.get('strategy')}};if(f.get('fallbackTag'))x.fallbackTag=f.get('fallbackTag');if(index==null)bs.push(x);else bs[index]=x;v.balancers=bs;await saveSection('routing',v);closeDialog();});}
async function deleteBalancer(index){let v=(await api('/api/settings/routing')).value||{},bs=v.balancers||[],tag=bs[index]?.tag;if((v.rules||[]).some(r=>r.balancerTag===tag))throw Error(L('Routing rules still reference this balancer.','Ruleهای روتینگ هنوز به این Balancer وصل هستند.'));bs.splice(index,1);v.balancers=bs;await saveSection('routing',v);}
async function editObservatory(){let o=(await api('/api/settings/observatory')).value||{};dialog('Observatory',`<div class="xv2-form">${field('subjectSelector','subjectSelector',(o.subjectSelector||[]).join(','))}${field('probeURL','probeURL',o.probeURL||'https://www.gstatic.com/generate_204','url')}${field('probeInterval','probeInterval',o.probeInterval||'30s')}${select('enableConcurrency','enableConcurrency',[['false','false'],['true','true']],String(!!o.enableConcurrency))}</div>`,async f=>{let v={subjectSelector:csv(f.get('subjectSelector')),probeURL:f.get('probeURL'),probeInterval:f.get('probeInterval'),enableConcurrency:f.get('enableConcurrency')==='true'};await saveSection('observatory',v);closeDialog();});}
runAction=async function(act,el){if(act==='xv2tab'){state.xv2.tab=el.dataset.tab;state.page='xray';shell();await renderPage();return;}if(act==='xv2validate'){await api('/api/core/validate','POST',{});toast(L('Xray candidate is valid.','پیکربندی Xray معتبر است.'));return;}if(act==='xv2restart'){if(confirm(L('Apply and restart Xray? Active sessions can disconnect.','اعمال و ری‌استارت Xray؟ اتصال‌ها ممکن است قطع شوند.'))){await api('/api/core/restart','POST',{});await refresh();}return;}if(act==='xv2dnsedit'){await editDNS();return;}if(act==='xv2outnew'){await editOutbound();return;}if(act==='xv2outedit'){await editOutbound(Number(el.dataset.index));return;}if(act==='xv2outclone'){await editOutbound(Number(el.dataset.index),true);return;}if(act==='xv2outdelete'){let list=(await api('/api/settings/outbounds')).value||[];if(list.length<=1)throw Error(L('At least one outbound is required.','حداقل یک Outbound لازم است.'));if(confirm(L('Delete outbound? Dependent routing rules will block unsafe removal.','Outbound حذف شود؟ وابستگی‌های Routing حذف ناامن را رد می‌کنند.'))){list.splice(Number(el.dataset.index),1);await saveSection('outbounds',list);}return;}if(act==='xv7smartpreview'){await smartRoutingPreview();return;}if(act==='xv7warpscan'){await scanSmartWarpPage();return;}if(act==='xv7gotooutbounds'){state.page='xray';state.xv2.tab='outbounds';shell();await renderPage();return;}if(act==='xv7gotonodes'){state.page='nodes';shell();await renderPage();return;}if(act==='xv7smartoutpreview'){await smartRoutingOutboundPreview();return;}if(act==='xv7smartsafety'){await runSmartSafety(el.dataset.revision);return;}if(act==='xv7smartrollout'){await startSmartRollout(el.dataset.revision);return;}if(act==='xv7rolloutpause'){await controlSmartRollout(el.dataset.rollout,'pause');return;}if(act==='xv7rolloutresume'){await controlSmartRollout(el.dataset.rollout,'resume');return;}if(act==='xv7rolloutabort'){await controlSmartRollout(el.dataset.rollout,'abort');return;}if(act==='xv7rollouttimeline'){await showRolloutTimeline(el.dataset.rollout);return;}if(act==='xv7smartapply'){await activateSmartRevision(el.dataset.revision);return;}if(act==='xv7smartrollback'){await rollbackSmartRevision(el.dataset.revision);return;}if(act==='xv2routesettings'){await routeSettings();return;}if(act==='xv2rulenew'){await editRule();return;}if(act==='xv2ruleedit'){await editRule(Number(el.dataset.index));return;}if(act==='xv2ruledelete'){await mutateRule(Number(el.dataset.index),'delete');return;}if(act==='xv2ruleup'){await mutateRule(Number(el.dataset.index),'up');return;}if(act==='xv2ruledown'){await mutateRule(Number(el.dataset.index),'down');return;}if(act==='xv2balnew'){await editBalancer();return;}if(act==='xv2baledit'){await editBalancer(Number(el.dataset.index));return;}if(act==='xv2baldelete'){await deleteBalancer(Number(el.dataset.index));return;}if(act==='xv2obsedit'){await editObservatory();return;}return baseRunAction(act,el);};
})();
